53	static void ReadComplete(const FPGA::SamplingResult &result) {
54		bool needs_work = false;
55		switch(activeMode) {
56		case HW::Mode::VNA:
57			needs_work = VNA::MeasurementDone(result);
58			break;
59		case HW::Mode::Manual:
60			needs_work = Manual::MeasurementDone(result);
61			break;
62		case HW::Mode::SA:
63			needs_work = SA::MeasurementDone(result);
64			break;
65		default:
66			break;
67		}
68		if(needs_work) {
69			STM::DispatchToInterrupt(HW::Work);
70		}
71	}
