94	bool HW::Init() {
95	#if USE_DEBUG_PINS
96		// initialize debug pins
97		GPIO_InitTypeDef gpio;
98		gpio.Pin = DEBUG1_PIN;
99		gpio.Mode = GPIO_MODE_OUTPUT_PP;
100		gpio.Speed = GPIO_SPEED_HIGH;
101		HAL_GPIO_Init(DEBUG1_GPIO, &gpio);
102		gpio.Pin = DEBUG2_PIN;
103		HAL_GPIO_Init(DEBUG2_GPIO, &gpio);
104	#endif
105		LOG_DEBUG("Initializing...");
106	
107		activeMode = Mode::Idle;
108	
109		LoadDeviceConfig();
110	
111		Si5351.Init();
112	
113		// Use Si5351 to generate reference frequencies for other PLLs and ADC
114		Si5351.SetPLL(Si5351C::PLL::A, HW::SI5351CPLLConstantFrequency, Si5351C::PLLSource::XTAL);
115		while(!Si5351.Locked(Si5351C::PLL::A));
116	
117		Si5351.SetPLL(Si5351C::PLL::B, HW::SI5351CPLLAlignedFrequency, Si5351C::PLLSource::XTAL);
118		while(!Si5351.Locked(Si5351C::PLL::B));
119	
120		extRefInUse = 0;
121		extOutFreq = 0;
122		Si5351.Disable(SiChannel::ReferenceOut);
123	
124		// Both MAX2871 get a 100MHz reference
125	//	Si5351.SetBypass(SiChannel::Source, Si5351C::PLLSource::XTAL);
126		Si5351.SetCLK(SiChannel::Source, HW::PLLRef, Si5351C::PLL::A, Si5351C::DriveStrength::mA8);
127		Si5351.Enable(SiChannel::Source);
128	//	Si5351.SetBypass(SiChannel::LO1, Si5351C::PLLSource::XTAL);
129		Si5351.SetCLK(SiChannel::LO1, HW::PLLRef, Si5351C::PLL::A, Si5351C::DriveStrength::mA8);
130		Si5351.Enable(SiChannel::LO1);
131		// 16MHz FPGA clock
132		Si5351.SetCLK(SiChannel::FPGA, HW::FPGAClkInFrequency, Si5351C::PLL::A, Si5351C::DriveStrength::mA8);
133		Si5351.Enable(SiChannel::FPGA);
134	
135		// Generate second LO with Si5351
136		// The 2.LO frequency is only set up here once. The frequencies chosen for DefaultLO2 and PLL B must
137		// have an integer divisor. When changing the 2.LO frequency after this point, the PLL B frequency is
138		// changed instead of modifying the clock output dividers. Otherwise, phase reversal may happen
139		// intermittently at one or multiple 2.LO outputs. See also https://github.com/jankae/LibreVNA/issues/280
140		Si5351.SetCLK(SiChannel::Port1LO2, DefaultLO2, Si5351C::PLL::B, Si5351C::DriveStrength::mA2);
141		Si5351.Enable(SiChannel::Port1LO2);
142		Si5351.SetCLK(SiChannel::Port2LO2, DefaultLO2, Si5351C::PLL::B, Si5351C::DriveStrength::mA2);
143		Si5351.Enable(SiChannel::Port2LO2);
144		Si5351.SetCLK(SiChannel::RefLO2, DefaultLO2, Si5351C::PLL::B, Si5351C::DriveStrength::mA2);
145		Si5351.Enable(SiChannel::RefLO2);
146	
147		// PLL reset appears to realign phases of clock signals
148		Si5351.ResetPLL(Si5351C::PLL::B);
149	
150		if(Si5351.WaitForLock(Si5351C::PLL::B, 10)) {
151			LOG_DEBUG("Si5351 locked");
152		}
153	
154		// FPGA clock is now present, can initialize
155		if (!FPGA::Init(HaltedCallback)) {
156			LOG_ERR("Aborting due to uninitialized FPGA");
157			return false;
158		}
159	
160		FPGA::DisableHardwareOverwrite();
161	
162		// Set default ADC samplerate
163		FPGA::WriteRegister(FPGA::Reg::ADCPrescaler, deviceConfig.config.V1.ADCprescaler);
164		// Set phase increment according to
165		FPGA::WriteRegister(FPGA::Reg::PhaseIncrement, deviceConfig.config.V1.DFTphaseInc);
166	
167		// Set default settling time
168		FPGA::SetSettlingTime(deviceConfig.config.V1.PLLSettlingDelay);
169	
170		Exti::SetCallback(FPGA_INTR_GPIO_Port, FPGA_INTR_Pin, Exti::EdgeType::Rising, Exti::Pull::Down, FPGA_Interrupt);
171	
172		// Initialize PLLs and build VCO maps
173		// enable source synthesizer
174		FPGA::Enable(FPGA::Periphery::SourceChip);
175		FPGA::SetMode(FPGA::Mode::SourcePLL);
176		Source.Init(HW::PLLRef, false, 1, false);
177		Source.SetPowerOutA(MAX2871::Power::n4dbm);
178		// output B is not used
179		Source.SetPowerOutB(MAX2871::Power::n4dbm, false);
180		if(!Source.BuildVCOMap()) {
181			LOG_WARN("Source VCO map failed");
182		} else {
183			LOG_INFO("Source VCO map complete");
184		}
185		Source.SetFrequency(1000000000);
186		Source.UpdateFrequency();
187		LOG_DEBUG("Source temp: %u", Source.GetTemp());
188		// disable source synthesizer/enable LO synthesizer
189		FPGA::SetMode(FPGA::Mode::FPGA);
190		FPGA::Disable(FPGA::Periphery::SourceChip);
191		FPGA::Enable(FPGA::Periphery::LO1Chip);
192		FPGA::SetMode(FPGA::Mode::LOPLL);
193		LO1.Init(HW::PLLRef, false, 1, false);
194		LO1.SetPowerOutA(MAX2871::Power::n4dbm);
195		LO1.SetPowerOutB(MAX2871::Power::n4dbm);
196		if(!LO1.BuildVCOMap()) {
197			LOG_WARN("LO1 VCO map failed");
198		} else {
199			LOG_INFO("LO1 VCO map complete");
200		}
201		LO1.SetFrequency(1000000000 + deviceConfig.config.V1.IF1);
202		LO1.UpdateFrequency();
203		LOG_DEBUG("LO temp: %u", LO1.GetTemp());
204	
205		FPGA::SetMode(FPGA::Mode::FPGA);
206		// disable both synthesizers
207		FPGA::Disable(FPGA::Periphery::LO1Chip);
208		FPGA::WriteMAX2871Default(Source.GetRegisters());
209	
210		LOG_INFO("Initialized");
211		FPGA::Enable(FPGA::Periphery::ReadyLED);
212	
213		Ref::update();
214		return true;
215	}
