217	void HW::SetMode(Mode mode) {
218		if(activeMode == mode) {
219			// already the correct mode
220			return;
221		}
222		unlevel = false;
223		switch(activeMode) {
224		case Mode::Manual:
225			Manual::Stop();
226			break;
227		case Mode::VNA:
228			VNA::Stop();
229			break;
230		default:
231			break;
232		}
233		if(mode != Mode::Idle) {
234			// do a full initialization when switching directly between modes
235			HW::Init();
236			lastISR = Delay::get_us();
237		}
238		SetIdle();
239		activeMode = mode;
240	}
