272	HW::AmplitudeSettings HW::GetAmplitudeSettings(int16_t cdbm, uint64_t freq, bool applyCorrections, bool port2) {
273		if (applyCorrections) {
274			auto correction = Cal::SourceCorrection(freq);
275			if (port2) {
276				cdbm += correction.port2;
277			} else {
278				cdbm += correction.port1;
279			}
280		}
281		AmplitudeSettings ret;
282		if(freq < BandSwitchFrequency) {
283			if(cdbm <= HW::LowBandMinPower) {
284				// can use the low power setting
285				ret.lowBandPower = Si5351C::DriveStrength::mA2;
286				cdbm -= HW::LowBandMinPower;
287			} else {
288				// needs the high power setting
289				ret.lowBandPower = Si5351C::DriveStrength::mA8;
290				cdbm -= HW::LowBandMaxPower;
291			}
292		} else {
293			if(cdbm <= HW::HighBandMinPower) {
294				// can use the low power setting
295				ret.highBandPower = MAX2871::Power::n4dbm;
296				cdbm -= HW::HighBandMinPower;
297			} else {
298				// needs the high power setting
299				ret.highBandPower = MAX2871::Power::p5dbm;
300				cdbm -= HW::HighBandMaxPower;
301			}
302		}
303		// calculate required attenuation
304		int16_t attval = -cdbm / 25;
305		if(attval > 127) {
306			attval = 127;
307			ret.unlevel = true;
308		} else if(attval < 0) {
309			attval = 0;
310			ret.unlevel = true;
311		} else {
312			ret.unlevel = false;
313		}
314		ret.attenuator = attval;
315		return ret;
316	}
