318	bool HW::TimedOut() {
319		constexpr uint64_t timeout = 1000000;
320		auto bufISR = lastISR;
321		uint64_t now = Delay::get_us();
322		uint64_t timeSinceLast = now - bufISR;
323		if(activeMode != Mode::Idle && activeMode != Mode::Generator && !VNA::IsWaitingInStandby() && timeSinceLast > timeout) {
324			LOG_WARN("Timed out, last ISR was at %lu%06lu, now %lu%06lu"
325					, (uint32_t) (bufISR / 1000000), (uint32_t)(bufISR%1000000)
326					, (uint32_t) (now / 1000000), (uint32_t)(now%1000000));
327			if(activeMode == Mode::VNA) {
328				VNA::PrintStatus();
329			}
330			return true;
331		} else {
332			return false;
333		}
334	}
