340	void HW::getDeviceStatus(Protocol::DeviceStatus *status, bool updateEvenWhenBusy) {
341		if(activeMode == Mode::Idle || updateEvenWhenBusy) {
342			// updating values from FPGA allowed
343	
344			// read PLL temperatures
345			uint8_t tempSource, tempLO;
346			GetTemps(&tempSource, &tempLO);
347			LOG_INFO("PLL temperatures: %u/%u", tempSource, tempLO);
348			// Read ADC min/max
349			auto limits = FPGA::GetADCLimits();
350			LOG_INFO("ADC limits: P1: %d/%d P2: %d/%d R: %d/%d",
351					limits.P1min, limits.P1max, limits.P2min, limits.P2max,
352					limits.Rmin, limits.Rmax);
353		#define ADC_LIMIT 		27000
354			if(limits.P1min < -ADC_LIMIT || limits.P1max > ADC_LIMIT
355					|| limits.P2min < -ADC_LIMIT || limits.P2max > ADC_LIMIT
356					|| limits.Rmin < -ADC_LIMIT || limits.Rmax > ADC_LIMIT) {
357				status->V1.ADC_overload = true;
358			} else {
359				status->V1.ADC_overload = false;
360			}
361			auto FPGA_status = FPGA::GetStatus();
362			status->V1.LO1_locked = (FPGA_status & (int) FPGA::Interrupt::LO1Unlock) ? 0 : 1;
363			status->V1.source_locked = (FPGA_status & (int) FPGA::Interrupt::SourceUnlock) ? 0 : 1;
364			status->V1.extRefAvailable = Ref::available();
365			status->V1.extRefInUse = Ref::usingExternal();
366			status->V1.unlevel = unlevel;
367			status->V1.temp_LO1 = tempLO;
368			status->V1.temp_source = tempSource;
369			FPGA::ResetADCLimits();
370		}
371		status->V1.temp_MCU = STM::getTemperature();
372	}
