386	void HW::Ref::update() {
387		if(extOutFreq != ref.ExtRefOuputFreq) {
388			extOutFreq = ref.ExtRefOuputFreq;
389			if(extOutFreq == 0) {
390				Si5351.Disable(SiChannel::ReferenceOut);
391				LOG_INFO("External reference output disabled");
392			} else {
393				Si5351.SetCLK(SiChannel::ReferenceOut, extOutFreq, Si5351C::PLL::A);
394				Si5351.Enable(SiChannel::ReferenceOut);
395				LOG_INFO("External reference output set to %luHz", extOutFreq);
396			}
397		}
398		bool useExternal = ref.UseExternalRef;
399		if (ref.AutomaticSwitch) {
400			useExternal = Ref::available();
401		}
402		if(useExternal != extRefInUse) {
403			// switch between internal and external reference
404			extRefInUse = useExternal;
405			if(extRefInUse) {
406				if(!Ref::available()) {
407					LOG_WARN("Forced switch to external reference but no signal detected");
408				}
409				Si5351.ConfigureCLKIn(10000000);
410				Si5351.SetPLL(Si5351C::PLL::A, HW::SI5351CPLLConstantFrequency, Si5351C::PLLSource::CLKIN);
411				Si5351.SetPLL(Si5351C::PLL::B, HW::SI5351CPLLAlignedFrequency, Si5351C::PLLSource::CLKIN);
412				LOG_INFO("Switched to external reference");
413				FPGA::Enable(FPGA::Periphery::ExtRefLED);
414			} else {
415				Si5351.SetPLL(Si5351C::PLL::A, HW::SI5351CPLLConstantFrequency, Si5351C::PLLSource::XTAL);
416				Si5351.SetPLL(Si5351C::PLL::B, HW::SI5351CPLLAlignedFrequency, Si5351C::PLLSource::XTAL);
417				LOG_INFO("Switched to internal reference");
418				FPGA::Disable(FPGA::Periphery::ExtRefLED);
419			}
420		}
421		constexpr uint32_t lock_timeout = 100;
422		uint32_t start = HAL_GetTick();
423		while(!Si5351.Locked(Si5351C::PLL::A) || !Si5351.Locked(Si5351C::PLL::A)) {
424			if(HAL_GetTick() - start > lock_timeout) {
425				LOG_ERR("Clock distributor PLLs failed to lock");
426				return;
427			}
428		}
429	}
