439	static void updateOtherParametersFromProtocolDeviceConfig() {
440		float ADCrate = (float) FPGA::Clockrate / deviceConfig.config.V1.ADCprescaler;
441		deviceConfig.IF2 = ADCrate * deviceConfig.config.V1.DFTphaseInc / 4096;
442		deviceConfig.ADCsamplerate = ADCrate;
443	}
