486	void HW::updateDeviceStatus() {
487		if(StatusUpdateFlag && (activeMode == Mode::Idle || activeMode == Mode::Generator)) {
488			static uint32_t last_update = 0;
489			if(HAL_GetTick() - last_update >= 1000) {
490				last_update = HAL_GetTick();
491				HW::Ref::update();
492				Protocol::PacketInfo packet;
493				packet.type = Protocol::PacketType::DeviceStatus;
494				// Enable PLL chips for temperature reading
495				bool srcEn = FPGA::IsEnabled(FPGA::Periphery::SourceChip);
496				bool LOEn = FPGA::IsEnabled(FPGA::Periphery::LO1Chip);
497				FPGA::Enable(FPGA::Periphery::SourceChip);
498				FPGA::Enable(FPGA::Periphery::LO1Chip);
499				HW::getDeviceStatus(&packet.status, true);
500				// restore PLL state
501				FPGA::Enable(FPGA::Periphery::SourceChip, srcEn);
502				FPGA::Enable(FPGA::Periphery::LO1Chip, LOEn);
503				Communication::Send(packet);
504			}
505		}
506	}
