516	bool HW::LoadDeviceConfig() {
517		HWHAL::flash.read(flash_address, sizeof(deviceConfig), &deviceConfig);
518		if(deviceConfig.version != deviceConfigVersion) {
519			LOG_WARN("Invalid version in flash, expected %u, got %u", deviceConfigVersion, deviceConfig.version);
520			SetDefaultDeviceConfig();
521			return false;
522		} else {
523			LOG_INFO("Device config loaded from flash");
524			return true;
525		}
526	}
527	
528	bool HW::SaveDeviceConfig() {
529		if(!HWHAL::flash.eraseRange(flash_address, flash_size)) {
530			return false;
531		}
532		uint32_t write_size = sizeof(deviceConfig);
533		if(write_size % Flash::PageSize != 0) {
534			// round up to next page
535			write_size += Flash::PageSize - write_size % Flash::PageSize;
536		}
537		return HWHAL::flash.write(flash_address, write_size, &deviceConfig);
538	}
539	
540	void HW::SetDefaultDeviceConfig() {
541		memset(&deviceConfig, 0, sizeof(deviceConfig));
542		deviceConfig.version = deviceConfigVersion;
543		deviceConfig.config.V1.IF1 = HW::DefaultIF1;
544		deviceConfig.config.V1.ADCprescaler = HW::DefaultADCprescaler;
545		deviceConfig.config.V1.DFTphaseInc = HW::DefaultDFTphaseInc;
546		deviceConfig.config.V1.PLLSettlingDelay = HW::DefaultPLLSettlingDelay;
547		updateOtherParametersFromProtocolDeviceConfig();
548		LOG_INFO("Device config set to default");
549	}
