7	#define LOG_LEVEL	LOG_LEVEL_INFO
8	#define LOG_MODULE	"SI5351"
9	#include "Log.h"
10	
11	bool Si5351C::Init(uint32_t clkin_freq) {
12		bool success = true;
13		FreqCLKINDiv = 0;
14	
15		// Disable OEB pin functionality
16		success &= WriteRegister(Reg::OEBPinMask, 0xFF);
17		// Disable all outputs
18		success &= WriteRegister(Reg::OutputEnableControl, 0xFF);
19	
20		// Enable fanouts
21		success &= WriteRegister(Reg::FanoutEnable, 0xD0);
22	
23		if(success) {
24			LOG_INFO("Initialized");
25		} else {
26			LOG_ERR("Initialization failed");
27		}
28		return success;
29	}
30	
31	bool Si5351C::ConfigureCLKIn(uint32_t clkin_freq) {
32		bool success = true;
33	
34		uint8_t clkinDiv = 0;
35		while (clkin_freq / (1 << clkinDiv) > 40000000) {
36			if (clkinDiv < 3) {
37				clkinDiv++;
38			} else {
39				LOG_ERR("CLK in too high");
40				return false;
41			}
42		}
43		FreqCLKINDiv = clkin_freq / (1 << clkinDiv);
44		// Write CLK in divider
45		uint8_t value;
46		success &= ReadRegister(Reg::PLLInputSource, &value);
47		value &= ~0xC0;
48		value |= clkinDiv << 6;
49		success &= WriteRegister(Reg::PLLInputSource, value);
50	
51		return success;
52	}
53	
54	bool Si5351C::SetPLL(PLL pll, uint32_t frequency, PLLSource src, bool exactFrequency) {
55		if (frequency < 600000000 || frequency > 900000000) {
56			LOG_ERR("Requested PLL frequency out of range (600-900MHz): %lu", frequency);
57			return false;
58		}
59		PLLConfig c;
60		c.IntegerMode = false;
61		c.source = src;
62	
63		uint32_t srcFreq = src == PLLSource::XTAL ? FreqXTAL : FreqCLKINDiv;
64		// see https://www.silabs.com/documents/public/application-notes/AN619.pdf (page 3)
65		uint64_t div27 = (uint64_t) frequency * (1UL << 27) / srcFreq;
66		// Check for valid range
67		if (div27 < 15 * (1ULL << 27) || div27 > 90 * (1ULL << 27)) {
68			LOG_ERR("Calculated divider out of range (15-90)");
69			return false;
70		}
71		FindOptimalDivider(frequency, srcFreq, c.P1, c.P2, c.P3, exactFrequency);
72	
73		FreqPLL[(int) pll] = frequency;
74		LOG_DEBUG("Setting PLL %c to %luHz", pll==PLL::A ? 'A' : 'B', frequency);
75		return WritePLLConfig(c, pll);
76	}
77	
78	bool Si5351C::SetCLK(uint8_t clknum, uint32_t frequency, PLL source, DriveStrength strength, bool exactFrequency) {
79		ClkConfig c;
80		c.DivideBy4 = false;
81		c.IntegerMode = false;
82		c.Inverted = false;
83		c.PoweredDown = false;
84		c.RDiv = 1;
85		c.source = source;
86		c.strength = strength;
87	
88		uint32_t pllFreq = FreqPLL[(int) source];
89		if (clknum > 5) {
90			// outputs 6 and 7 are integer dividers only
91			uint32_t div = pllFreq / frequency;
92			if (div > 254 || div < 6) {
93				LOG_ERR("Divider on CLK6/7 out of range (6-254), would need %lu", div);
94				return false;
95			}
96			if(div & 0x01) {
97				LOG_ERR("Divider on CLK6/7 must be even, clock frequency will not match exactly");
98			}
99			div &= 0xFE;
100			uint32_t actualFreq = pllFreq / div;
101			uint32_t deviation = abs(frequency - actualFreq);
102			if (deviation > 0) {
103				LOG_WARN("Optimal divider for %luHz/%luHz is: %u (%luHz deviation)",
104						pllFreq, frequency, div, abs(frequency - actualFreq));
105			}
106			c.P1 = div;
107		} else {
108			while (pllFreq / (frequency * c.RDiv) >= 2048
109					|| (frequency * c.RDiv) < 500000) {
110				if (c.RDiv < 128) {
111					c.RDiv *= 2;
112				} else {
113					LOG_ERR("Unable to reach requested frequency");
114					return false;
115				}
116			}
117			FindOptimalDivider(pllFreq, frequency * c.RDiv, c.P1, c.P2, c.P3, exactFrequency);
118		}
119		LOG_DEBUG("Setting CLK%d to %luHz", clknum, frequency);
120		return WriteClkConfig(c, clknum);
121	}
122	
123	bool Si5351C::SetBypass(uint8_t clknum, PLLSource source, DriveStrength strength) {
124		// compile CLKControl register
125		uint8_t clkcontrol = 0x00;
126		if (source == PLLSource::CLKIN) {
127			clkcontrol |= 0x04;
128		}
129		switch (strength) {
130		case DriveStrength::mA2:
131			break;
132		case DriveStrength::mA4:
133			clkcontrol |= 0x01;
134			break;
135		case DriveStrength::mA6:
136			clkcontrol |= 0x02;
137			break;
138		case DriveStrength::mA8:
139			clkcontrol |= 0x03;
140			break;
141		}
142		Reg reg = (Reg) ((int) Reg::CLK0Control + clknum);
143		return WriteRegister(reg, clkcontrol);
144	}
145	
146	bool Si5351C::SetCLKtoXTAL(uint8_t clknum) {
147		Reg reg = (Reg) ((int) Reg::CLK0Control + clknum);
148		LOG_INFO("Connecting CLK%d to XTAL", clknum);
149		return ClearBits(reg, 0x0C);
150	}
151	bool Si5351C::SetCLKToCLKIN(uint8_t clknum) {
152		Reg reg = (Reg) ((int) Reg::CLK0Control + clknum);
153		LOG_INFO("Connecting CLK%d to CLK in", clknum);
154		return ClearBits(reg, 0x08) && SetBits(reg, 0x04);
155	}
156	
157	bool Si5351C::Enable(uint8_t clknum) {
158		LOG_INFO("Enabling CLK%d", clknum);
159		return ClearBits(Reg::OutputEnableControl, 1 << clknum);
160	}
161	
162	bool Si5351C::Disable(uint8_t clknum) {
163		LOG_INFO("Disabling CLK%d", clknum);
164		return SetBits(Reg::OutputEnableControl, 1 << clknum);
165	}
166	
167	bool Si5351C::Locked(PLL pll) {
168		uint8_t mask = pll == PLL::A ? 0x20 : 0x40;
169		uint8_t value;
170		ReadRegister(Reg::DeviceStatus, &value);
171		LOG_DEBUG("Device status: 0x%02x", value);
172		if (value & mask) {
173			return false;
174		} else {
175			return true;
176		}
177	}
178	
179	bool Si5351C::WaitForLock(PLL pll, uint32_t timeout) {
180		uint32_t start = HAL_GetTick();
181		while(HAL_GetTick() - start <= timeout) {
182			if(Locked(pll)) {
183				return true;
184			}
185		}
186		LOG_WARN("Failed to lock");
187		return false;
188	}
189	
190	bool Si5351C::WritePLLConfig(PLLConfig config, PLL pll) {
191		uint8_t PllData[8];
192		// See register map in https://www.silabs.com/documents/public/application-notes/AN619.pdf (page 11)
193		PllData[0] = (config.P3 >> 8) & 0xFF;
194		PllData[1] = config.P3 & 0xFF;
195		PllData[2] = (config.P1 >> 16) & 0x03;
196		PllData[3] = (config.P1 >> 8) & 0xFF;
197		PllData[4] = config.P1 & 0xFF;
198		PllData[5] = ((config.P3 >> 12) & 0xF0) | ((config.P2 >> 16) & 0x0F);
199		PllData[6] = (config.P2 >> 8) & 0xFF;
200		PllData[7] = config.P2 & 0xFF;
201		// Check if integer mode is applicable
202		Reg reg = pll == PLL::A ? Reg::CLK6Control : Reg::CLK7Control;
203		if (config.P2 == 0 && config.P1 % 128 == 0) {
204			SetBits(reg, 0x40);
205		} else {
206			ClearBits(reg, 0x40);
207		}
208		bool success = true;
209		reg = pll == PLL::A ? Reg::MSNA_CONFIG : Reg::MSNB_CONFIG;
210		success &= WriteRegisterRange(reg, PllData, sizeof(PllData));
211		reg = pll == PLL::A ? Reg::CLK6Control : Reg::CLK7Control;
212		if (config.IntegerMode) {
213			success &=SetBits(reg, 0x40);
214		} else {
215			success &=ClearBits(reg, 0x40);
216		}
217		uint8_t mask = pll == PLL::A ? 0x04 : 0x08;
218		if (config.source == PLLSource::XTAL) {
219			success &=ClearBits(Reg::PLLInputSource, mask);
220		} else {
221			success &=SetBits(Reg::PLLInputSource, mask);
222		}
223		return success;
224	}
225	
226	bool Si5351C::WriteClkConfig(ClkConfig config, uint8_t clknum) {
227		bool success = true;
228		// compile CLKControl register
229		uint8_t clkcontrol = 0x0C;
230		if (config.PoweredDown) {
231			clkcontrol |= 0x80;
232		}
233		if (clknum <= 5) {
234			if (config.IntegerMode) {
235				clkcontrol |= 0x40;
236			}
237		} else {
238			// preserve bit 6
239			uint8_t value = 0x00;
240			success &= ReadRegister((Reg) ((int) Reg::CLK0Control + clknum),
241					&value);
242			clkcontrol |= value & 0x40;
243		}
244		if (config.source == PLL::B) {
245			clkcontrol |= 0x20;
246		}
247		if (config.Inverted) {
248			clkcontrol |= 0x10;
249		}
250		switch (config.strength) {
251		case DriveStrength::mA2:
252			break;
253		case DriveStrength::mA4:
254			clkcontrol |= 0x01;
255			break;
256		case DriveStrength::mA6:
257			clkcontrol |= 0x02;
258			break;
259		case DriveStrength::mA8:
260			clkcontrol |= 0x03;
261			break;
262		}
263		// Check if integer mode is applicable
264		if(config.P2 == 0 && config.P1%128 == 0) {
265			// Use integer mode
266			clkcontrol |= 0x40;
267		}
268		Reg reg = (Reg) ((int) Reg::CLK0Control + clknum);
269		success &= WriteRegister(reg, clkcontrol);
270		if (clknum <= 5) {
271			uint8_t ClkData[8];
272			ClkData[0] = (config.P3 >> 8) & 0xFF;
273			ClkData[1] = config.P3 & 0xFF;
274			ClkData[2] = (31 - __builtin_clz(config.RDiv)) << 4
275					| (config.DivideBy4 ? 0xC0 : 0x00) | ((config.P1 >> 16) & 0x03);
276			ClkData[3] = (config.P1 >> 8) & 0xFF;
277			ClkData[4] = config.P1 & 0xFF;
278			ClkData[5] = ((config.P3 >> 12) & 0xF0) | ((config.P2 >> 16) & 0x0F);
279			ClkData[6] = (config.P2 >> 8) & 0xFF;
280			ClkData[7] = config.P2 & 0xFF;
281	
282			// Calculate address of register control block
283			reg = (Reg) ((int) Reg::MS0_CONFIG + 8 * clknum);
284			success &= WriteRegisterRange(reg, ClkData, sizeof(ClkData));
285		} else if (clknum == 6) {
286			success &= WriteRegister(Reg::MS6_CONFIG, config.P1 & 0xFF);
287		} else {
288			success &= WriteRegister(Reg::MS7_CONFIG, config.P1 & 0xFF);
289		}
290	
291		return success;
292	}
293	
294	bool Si5351C::WriteRegister(Reg reg, uint8_t data) {
295		return WriteRegisterRange(reg, &data, 1);
296	}
