303	bool Si5351C::SetBits(Reg reg, uint8_t bits) {
304		uint8_t value = 0;
305		if (!ReadRegister(reg, &value)) {
306			return false;
307		}
308		value |= bits;
309		return WriteRegister(reg, value);
310	}
