312	bool Si5351C::ClearBits(Reg reg, uint8_t bits) {
313		uint8_t value = 0;
314		if (!ReadRegister(reg, &value)) {
315			return false;
316		}
317		value &= ~bits;
318		return WriteRegister(reg, value);
319	}
320	
321	bool Si5351C::WriteRegisterRange(Reg start, const uint8_t *data, uint8_t len) {
322		return HAL_I2C_Mem_Write(i2c, address, (int) start,
323		I2C_MEMADD_SIZE_8BIT, (uint8_t*) data, len, 100) == HAL_OK;
324	}
325	
326	bool Si5351C::ExtCLKAvailable() {
327		uint8_t value;
328		ReadRegister(Reg::DeviceStatus, &value);
329		if (value & 0x10) {
330			return false;
331		} else {
332			return true;
333		}
334	}
335	
336	bool Si5351C::ReadRegisterRange(Reg start, uint8_t *data, uint8_t len) {
337		return HAL_I2C_Mem_Read(i2c, address, (int) start,
338		I2C_MEMADD_SIZE_8BIT, data, len, 100) == HAL_OK;
339	}
340	
341	bool Si5351C::ResetPLL(PLL pll) {
342		if (pll == PLL::A) {
343			return SetBits(Reg::PLLReset, 0x20);
344		} else {
345			return SetBits(Reg::PLLReset, 0x80);
346		}
347	}
348	
349	void Si5351C::FindOptimalDivider(uint32_t f_pll, uint32_t f, uint32_t &P1,
350			uint32_t &P2, uint32_t &P3, bool exact) {
351		// see https://www.silabs.com/documents/public/application-notes/AN619.pdf (page 3/6)
352		uint32_t a = f_pll / f;
353		int32_t f_rem = f_pll - f * a;
354		uint32_t best_c;
355		uint32_t best_b;
356		if(exact) {
357			// spend the effort to find the best divider possible
358			Algorithm::RationalApproximation ratio;
359			ratio.num = f_rem;
360			ratio.denom = f;
361			auto approx = Algorithm::BestRationalApproximation(ratio, (1UL << 20) - 1);
362			best_c = approx.denom;
363			best_b = approx.num;
364		} else {
365			// just use the highest denominator possible, this is good enough if no exact frequency is required
366			best_c = (1UL << 20) - 1;
367			best_b = (uint64_t) f_rem * best_c / f;
368		}
369	
370		// convert to Si5351C parameters
371		uint32_t floor = 128 * best_b / best_c;
372		P1 = 128 * a + floor - 512;
373		P2 = 128 * best_b - best_c * floor;
374		P3 = best_c;
375		LOG_DEBUG("P1=%lu, P2=%lu, P3=%lu", P1, P2, P3);
376	}
377	
378	bool Si5351C::WriteRawCLKConfig(uint8_t clknum, const uint8_t *config) {
379		// Calculate address of register control block
380		auto reg = (Reg) ((int) Reg::MS0_CONFIG + 8 * clknum);
381		return WriteRegisterRange(reg, config, 8);
382	}
383	
