135	bool MAX2871::SetFrequency(uint64_t f) {
136		if (f < 23500000 || f > MaxFreq) {
137			LOG_ERR("Frequency must be between 23.5MHz and 6GHz, requested %lu%06luHz", (uint32_t ) (f / 1000000),
138					(uint32_t ) (f % 1000000));
139			return false;
140		}
141		LOG_DEBUG("Setting frequency to %lu%06luHz...", (uint32_t ) (f / 1000000),
142				(uint32_t ) (f % 1000000));
143		// select divider
144		uint64_t f_vco = f;
145		uint8_t div = 0;
146		if (f < 46875000) {
147			div = 0x07;
148			f_vco *= 128;
149		} else if (f < 93750000) {
150			div = 0x06;
151			f_vco *= 64;
152		} else if (f < 187500000) {
153			div = 0x05;
154			f_vco *= 32;
155		} else if (f < 375000000) {
156			div = 0x04;
157			f_vco *= 16;
158		} else if (f < 750000000) {
159			div = 0x03;
160			f_vco *= 8;
161		} else if (f < 1500000000) {
162			div = 0x02;
163			f_vco *= 4;
164		} else if (f < 3000000000) {
165			div = 0x01;
166			f_vco *= 2;
167		}
168		LOG_DEBUG("F_VCO: %lu%06luHz",
169				(uint32_t ) (f_vco / 1000000), (uint32_t ) (f_vco % 1000000));
170		if (gotVCOMap) {
171			// manual VCO selection for lock time improvement
172			uint16_t compare = f_vco / 100000;
173			uint8_t vco = 0;
174			for (; vco < 64; vco++) {
175				if (VCOmax[vco] >= compare) {
176					break;
177				}
178			} LOG_DEBUG("Manually selected VCO %d", vco);
179			regs[3] &= ~0xFC000000;
180			regs[3] |= (uint32_t) vco << 26;
181		}
182		uint16_t N = f_vco / f_PFD;
183		if (N < 19 || N > 4091) {
184			LOG_ERR("Invalid N value, should be between 19 and 4091, got %lu", N);
185			return false;
186		}
187		uint32_t rem_f = f_vco - N * f_PFD;
188		LOG_DEBUG("Remaining fractional frequency: %lu", rem_f);
189		LOG_DEBUG("Looking for best fractional match");
190		float fraction = (float) rem_f / f_PFD;
191	
192		Algorithm::RationalApproximation ratio;
193		ratio.num = rem_f;
194		ratio.denom = f_PFD;
195		auto approx = Algorithm::BestRationalApproximation(ratio, 4095);
196	
197		if (approx.denom == approx.num) {
198			// got an impossible result due to floating point limitations(?)
199			// Set fractional part to zero, increase integer part instead
200			approx.num = 0;
201			approx.denom = 2;
202			N++;
203		}
204	
205		if(approx.denom == 1) {
206			// M value must be at least 2
207			approx.denom = 2;
208		}
209	
210		int32_t rem_approx = ((uint64_t) f_PFD * approx.num) / approx.denom;
211		if(rem_approx != rem_f) {
212			LOG_WARN("Best match is F=%u/M=%u, deviation of %luHz",
213					approx.num, approx.denom, abs(rem_f - rem_approx));
214		}
215	
216		uint64_t f_set = (uint64_t) N * f_PFD + rem_approx;
217		f_set /= (1UL << div);
218	
219		// write values to registers
220		regs[4] &= ~0x00700000;
221		regs[4] |= ((uint32_t) div << 20);
222		regs[0] &= ~0x7FFFFFF8;
223		regs[0] |= ((uint32_t) N << 15) | ((uint32_t) approx.num << 3);
224		regs[1] &= ~0x00007FF8;
225		regs[1] |= ((uint32_t) approx.denom << 3);
226	
227		LOG_DEBUG("Set frequency to %lu%06luHz...",
228				(uint32_t ) (f_set / 1000000), (uint32_t ) (f_set % 1000000));
229		outputFrequency = f_set;
230		return true;
231	}
232	
233	bool MAX2871::SetReference(uint32_t f_ref, bool doubler, uint16_t r,
234			bool div2) {
235		if (f_ref < 10000000) {
236			LOG_ERR("Reference frequency must be >=10MHz, is %lu", f_ref);
237			return false;
238		} else if (f_ref > 105000000 && doubler) {
239			LOG_ERR(
240					"Reference frequency must be <=105MHz when used with doubler, is %lu",
241					f_ref);
242			return false;
243		} else if (f_ref > 210000000) {
244			LOG_ERR("Reference frequency must be <=210MHz, is %lu", f_ref);
245			return false;
246		}
247		if (r < 1 || r > 1023) {
248			LOG_ERR("Reference divider must be between 1 and 1023, is %d", r);
249			return false;
250		}
251		// calculate PFD frequency
252		uint32_t pfd = f_ref;
253		if (doubler) {
254			pfd *= 2;
255		}
256		pfd /= r;
257		if (div2) {
258			pfd /= 2;
259		}
260		if (pfd > 125000000) {
261			LOG_ERR("PFD frequency must be <=125MHz, is %d",
262					pfd);
263			return false;
264		}
265		if(pfd > 32000000) {
266			regs[2] |= (1UL << 31);
267		} else {
268			regs[2] &= ~(1UL << 31);
269		}
270		// input values are valid, adjust registers
271		regs[2] &= ~0x03FFC000;
272		if (doubler) {
273			regs[2] |= (1UL << 25);
274		}
275		if (div2) {
276			regs[2] |= (1UL << 24);
277		}
278		regs[2] |= (r << 14);
279		f_PFD = pfd;
280		LOG_INFO("Set PFD frequency to %lu", f_PFD);
281	
282		// updating VAS state machine clock
283		uint16_t BS = f_PFD / 50000;
284		if (BS > 1023) {
285			BS = 1023;
286		} else if (BS < 1) {
287			BS = 1;
288		}
289		LOG_DEBUG("BS set to %lu", BS);
290		regs[4] &= ~0x030FF000;
291		regs[4] |= ((BS & 0xFF) << 12);
292		regs[4] |= (((BS >> 8) & 0x03) << 24);
293	
294		// update ADC clock
295		uint16_t cdiv = f_PFD/100000;
296		LOG_DEBUG("CDIV set to %u", cdiv);
297		regs[3] &= ~0x00007FF8;
298		regs[3] |= (cdiv & 0xFFF) << 3;
299		return true;
300	}
