318	void MAX2871::Write(uint8_t reg, uint32_t val) {
319		uint8_t data[4];
320		// split value into two 16 bit words
321		data[0] = (val >> 24) & 0xFF;
322		data[1] = (val >> 16) & 0xFF;
323		data[2] = (val >> 8) & 0xFF;
324		data[3] = (val & 0xF8) | reg;
325		Delay::us(1);
326		HAL_SPI_Transmit(hspi, (uint8_t*) data, 4, 20);
327		LE->BSRR = LEpin;
328		Delay::us(1);
329		LE->BSRR = LEpin << 16;
330	}
