332	// Assumes that the MUX pin is already configured as "Read register 6" and connected to MISO
333	uint32_t MAX2871::Read() {
334		uint8_t transmit[4] = {0x00, 0x00, 0x00, 0x06};
335		HAL_SPI_Transmit(hspi, (uint8_t*) transmit, 4, 20);
336		LE->BSRR = LEpin;
337		memset(transmit, 0, sizeof(transmit));
338		uint8_t recv[4];
339		HAL_SPI_TransmitReceive(hspi, (uint8_t*) transmit, (uint8_t*) recv, 4, 20);
340		LE->BSRR = LEpin << 16;
341		// assemble readback result
342		uint32_t result = ((uint32_t) recv[0] << 24) | ((uint32_t) recv[1] << 16
343		) | ((uint32_t) recv[2] << 8) | (recv[3] & 0xFF);
344		result <<= 2;
345		LOG_DEBUG("Readback: 0x%08x", result);
346		return result;
347	}
