349	bool MAX2871::BuildVCOMap() {
350		memset(VCOmax, 0, sizeof(VCOmax));
351		// save output frequency
352		uint64_t oldFreq = outputFrequency;
353		constexpr uint32_t step = 10000000;
354		for (uint64_t freq = 3000000000; freq <= MaxFreq; freq += step) {
355			SetFrequency(freq);
356			UpdateFrequency();
357			uint32_t start = HAL_GetTick();
358			// set MUX to LD
359			regs[2] &= ~(7UL << 26);
360			regs[5] &= ~(1UL << 18);
361			regs[2] |= (6UL << 26);
362			Write(5, regs[5]);
363			Write(2, regs[2]);
364			while (!(MUX->IDR & MUXpin)) {
365				if (HAL_GetTick() - start > 100) {
366					LOG_ERR(
367							"Failed to lock during VCO map build process, aborting (f=%lu%06luHz)",
368							(uint32_t )(freq / 1000000),
369							(uint32_t ) (freq % 1000000));
370					gotVCOMap = false;
371					// revert back to previous frequency
372					SetFrequency(oldFreq);
373					LE->BSRR = LEpin << 16;
374					// Mux pin back to high impedance
375					regs[2] &= ~(7UL << 26);
376					regs[5] &= ~(1UL << 18);
377					Update();
378					return false;
379				}
380			}
381			// set MUX to SPI read
382			regs[2] &= ~(7UL << 26);
383			regs[5] &= ~(1UL << 18);
384			regs[2] |= (4UL << 26);
385			regs[5] |= (1UL << 18);
386			Write(5, regs[5]);
387			Write(2, regs[2]);
388			auto readback = Read();
389			uint8_t vco = (readback & 0x01F8) >> 3;
390			VCOmax[vco] = freq / 100000;
391			LOG_INFO("VCO map: %lu%06luHz uses VCO %d",
392				(uint32_t ) (freq / 1000000), (uint32_t ) (freq % 1000000), vco);
393		}
394		gotVCOMap = true;
395		// revert back to previous frequency
396		SetFrequency(oldFreq);
397		// Mux pin back to high impedance
398		regs[2] &= ~(7UL << 26);
399		regs[5] &= ~(1UL << 18);
400	
401		// Turn off VAS, select VCO manually from now on
402		regs[3] |= (1UL << 25);
403		Update();
404		return true;
405	}
406	
407	uint8_t MAX2871::GetTemp() {
408		// select temperature channel and start ADC
409		regs[5] &= ~0x00000078;
410		regs[5] |= 0x00000048;
411		Write(5, regs[5]);
412		Delay::us(100);
413		// set MUX to SPI read
414		regs[2] &= ~(7UL << 26);
415		regs[5] &= ~(1UL << 18);
416		regs[2] |= (4UL << 26);
417		regs[5] |= (1UL << 18);
418		Write(5, regs[5]);
419		Write(2, regs[2]);
420		uint8_t ADC_raw = (Read() >> 16) & 0x7F;
421		LOG_DEBUG("Raw temp ADC: %d", ADC_raw);
422		// Disable ADC
423		regs[5] &= ~0x00000078;
424		// Mux pin back to high impedance
425		regs[2] &= ~(7UL << 26);
426		regs[5] &= ~(1UL << 18);
427		Write(5, regs[5]);
428		Write(2, regs[2]);
429		// convert to celsius and return
430		return 95 - 1.14f * ADC_raw;
431	}
